import{d as _,C as a,o as u,c as x,j as n,a as t,E as e,a3 as z}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"庄子·马蹄","description":"残朴以为器，毁道德以为仁义——圣人之过。理解庄子对「善治」的批判。","frontmatter":{"title":"庄子·马蹄","description":"残朴以为器，毁道德以为仁义——圣人之过。理解庄子对「善治」的批判。","category":"guide","aliases":["马蹄","庄子马蹄","zhuangzi chapter 09"],"source":["《庄子·马蹄》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-09.md","filePath":"daoism/zhuang-zi/chapter-09.md","lastUpdated":1792641266000}'),b={name:"daoism/zhuang-zi/chapter-09.md"},j=_({...b,setup(c){const d=[{id:"mati_s1",label:"马，蹄可以践霜雪……此马之真性也",sentences:[["马，蹄可以",{text:"践",glossary:"jian_xue"},"霜雪，毛可以",{text:"御",glossary:"yu_han"},"风寒。"],[{text:"齕",glossary:"he_cao"},"草饮水，",{text:"翘足而陆",glossary:"qiao_lu"},"，此马之真性也。"],["虽有",{text:"义台路寝",glossary:"yi_tai_lu_qin"},"，",{text:"无所用之",glossary:"wu_yong"},"。"]]},{id:"mati_s2",label:"及至伯乐……马之死者十二三矣",sentences:[["及至伯乐，曰：「我",{text:"善",glossary:"shan_zhi"},"治马。」"],[{text:"烧之",glossary:"shao_zhi"},"，",{text:"剔之",glossary:"ti_zhi"},"，",{text:"刻之",glossary:"ke_zhi"},"，",{text:"雒之",glossary:"luo_zhi"},"。"],[{text:"连之",glossary:"lian_bian"},"以",{text:"羁絷",glossary:"ji_zhi"},"，",{text:"编之",glossary:"lian_bian"},"以",{text:"皂栈",glossary:"zao_zhan"},"，马之死者",{text:"十二三矣",glossary:"shi_er_san"},"！"]]},{id:"mati_s3",label:"饥之渴之……而马之死者已过半矣",sentences:[[{text:"饥之",glossary:"ji_ke"},{text:"渴之",glossary:"ji_ke"},"，",{text:"驰之",glossary:"chi_zhou"},{text:"骤之",glossary:"chi_zhou"},"，",{text:"整之",glossary:"zheng_qi"},{text:"齐之",glossary:"zheng_qi"},"，"],["前有",{text:"橛饰之患",glossary:"jue_shi"},"，而后有",{text:"鞭筴之威",glossary:"bian_ce"},"，而马之死者已过半矣！"]]},{id:"mati_s4",label:"陶者曰……直者应绳",sentences:[[{text:"陶者",glossary:"tao_zhe"},"曰：「我善",{text:"治埴",glossary:"zhi_zhi"},"。」",{text:"圆者中规",glossary:"zhong_gui_ju"},"，",{text:"方者中矩",glossary:"zhong_gui_ju"},"。"],["匠人曰：「我善治木。」",{text:"曲者中钩",glossary:"zhong_gou_sheng"},"，",{text:"直者应绳",glossary:"zhong_gou_sheng"},"。"]]},{id:"mati_s5",label:"夫埴木之性……此亦治天下者之过也",sentences:[["夫埴木之性，",{text:"岂欲",glossary:"qi_yu"},{text:"中",glossary:"zhong_he"},"规矩钩绳哉！"],["然且世世称之曰：「伯乐善治马，而陶匠善治埴木。」",{text:"此亦",glossary:"ci_yi"},{text:"治",glossary:"zhi_tianxia"},"天下者之",{text:"过",glossary:"zhi_tianxia"},"也。"]]}],m=[{id:"jian_xue",term:"践",pinyin:"jiàn",meaning:"踩踏·踏行。践：踩踏，读 jiàn。蹄可以践霜雪：马蹄可以踩踏霜雪——以马蹄践霜雪·毛御风寒，点出马的本然能力，是「真性」的第一层：天然适应自然环境。"},{id:"yu_han",term:"御",pinyin:"yù",meaning:"抵御·御寒。御：抵御，读 yù。毛可以御风寒：马毛可以抵御风寒——与「践霜雪」并举，共同描绘马的本然之性：无需人为加工，自然具备生存能力。"},{id:"he_cao",term:"齕",pinyin:"hé",meaning:"啃咬·吃草（以口啃食）。齕：啃咬，读 hé。齕草饮水：啃草喝水——马的本然饮食方式，自然简朴，与后文「饥之渴之」的人为控制形成对比。"},{id:"qiao_lu",term:"翘足而陆",pinyin:"qiào zú ér lù",meaning:"抬起蹄足腾跃嬉戏（自由奔跑跳跃）。翘：抬起·翘起；足：蹄足；陆：通「跳」，跳跃腾跃。翘足而陆：抬足腾跃——马自由嬉戏的本然状态，与后文「驰之骤之·整之齐之」的强制驱驰形成鲜明对比。"},{id:"yi_tai_lu_qin",term:"义台路寝",pinyin:"yì tái lù qǐn",meaning:"华美的高台与宽敞的宫室（人为建造的豪华居所）。义台：华美的高台；路寝：诸侯的正寝·宽敞的宫室，读 lù qǐn。虽有义台路寝，无所用之：即使有华美的台榭宫室，对马来说毫无用处——以「义台路寝」喻人为的华美设施，点出：人为之物对马的本然之性毫无意义。"},{id:"wu_yong",term:"无所用之",pinyin:"wú suǒ yòng zhī",meaning:"没有用处（对马来说毫无用处）。无所用：没有用处；之：指义台路寝。无所用之：对马来说毫无用处——点出人为建构（义台路寝）与马的本然之性的根本不相干，为后文伯乐「治马」的批判作铺垫。"},{id:"shan_zhi",term:"善",pinyin:"shàn",meaning:"擅长·善于（自夸精通某事）。善：擅长·善于，读 shàn。我善治马：我擅长驯治马——「善治……」是本节的反复句式（伯乐·陶者·匠人皆自称「善治」），庄子以「善治」引出批判：所谓「善治」，不过是以人为强加于本然，是「治天下者之过」的具体形态。"},{id:"shao_zhi",term:"烧之",pinyin:"shāo zhī",meaning:"用火烧灼（烙印·烧毛）。烧：烧灼，读 shāo；之：指马。烧之：用火烧灼马——指用烙铁烙印或烧去杂毛，是伯乐「治马」的第一道工序，以火伤马之本然。"},{id:"ti_zhi",term:"剔之",pinyin:"tī zhī",meaning:"剪剔毛发（修剪鬃毛）。剔：剪剔·修剪，读 tī；之：指马。剔之：剪剔马的鬃毛——修剪马的本然毛发，以人为审美改造马的自然形态。"},{id:"ke_zhi",term:"刻之",pinyin:"kè zhī",meaning:"刻削蹄甲（修削马蹄）。刻：刻削·修削，读 kè；之：指马。刻之：刻削马蹄——修削马蹄以符合人为标准，伤马蹄之本然。"},{id:"luo_zhi",term:"雒之",pinyin:"luò zhī",meaning:"烙印标记（用烙铁打上印记）。雒：通「烙」，烙印，读 luò；之：指马。雒之：给马打上烙印——以烙印标记所有权，是人为控制马的最后一道工序。烧·剔·刻·雒：四道工序并列，层层递进，描绘伯乐「治马」对马本然之性的系统性摧残。"},{id:"lian_bian",term:"连之·编之",pinyin:"lián zhī · biān zhī",meaning:"用……串连·用……编排（以器具约束马）。连：串连·连缀；编：编排·约束。连之以羁絷：用羁絷串连约束；编之以皂栈：用皂栈编排关押——「连·编」两个动词，描绘以羁絷·皂栈对马的外在束缚，与「烧·剔·刻·雒」的身体伤害并列，构成伯乐「治马」的完整暴力图景。"},{id:"ji_zhi",term:"羁絷",pinyin:"jī zhí",meaning:"马笼头与绳索（约束马头·马足的器具）。羁：马笼头·络头，读 jī；絷：绳索·绊马索，读 zhí。羁絷：笼头与绳索——以羁絷约束马的头部与足部，是外在束缚的象征，喻仁义礼法对人本然之性的束缚。"},{id:"zao_zhan",term:"皂栈",pinyin:"zào zhàn",meaning:"马厩与马槽（关押马匹的圈栏）。皂：马槽·马厩，读 zào；栈：栈道·圈栏，读 zhàn。皂栈：马厩圈栏——将马关押于皂栈，剥夺其自由奔跑的本然，与「翘足而陆」的自由状态形成对比。"},{id:"shi_er_san",term:"十二三矣",pinyin:"shí èr sān yǐ",meaning:"十分之二三（约百分之二三十）。十二三：十分之二三，古代分数表达法。马之死者十二三矣：马死去的已有十分之二三——以具体数字强调伯乐「治马」的死亡代价，为后文「已过半矣」的递进作铺垫。"},{id:"ji_ke",term:"饥之·渴之",pinyin:"jī zhī · kě zhī",meaning:"使马饥饿·使马干渴（以饥渴控制马）。饥：使……饥饿（使动用法）；渴：使……干渴（使动用法）。饥之渴之：让马饥饿·让马干渴——以饥渴作为驯马手段，是对马本然饮食（齕草饮水）的剥夺与控制。"},{id:"chi_zhou",term:"驰之·骤之",pinyin:"chí zhī · zhòu zhī",meaning:"使马奔驰·使马急跑（强制驱驰）。驰：使……奔驰（使动）；骤：使……急跑（使动），读 zhòu。驰之骤之：强制马奔驰急跑——以强制驱驰替代马本然的「翘足而陆」，是对马自由奔跑本性的强制异化。"},{id:"zheng_qi",term:"整之·齐之",pinyin:"zhěng zhī · qí zhī",meaning:"使马整齐·使马划一（强制规范马的行为）。整：使……整齐（使动）；齐：使……划一（使动）。整之齐之：强制马整齐划一——以人为规范约束马的本然行为，是「治马」的最后一层：从身体（烧剔刻雒）到束缚（羁絷皂栈）到驱驰（饥渴驰骤）到规范（整齐），层层递进。"},{id:"jue_shi",term:"橛饰之患",pinyin:"jué shì zhī huàn",meaning:"马口中嚼子与马身装饰的祸患。橛：马嚼子·衔铁，读 jué；饰：马身的装饰（马络·马鞍等）；患：祸患·威胁。橛饰之患：前方嚼子与装饰的威胁——「前有橛饰之患」指马前方受嚼子约束，是对马口·头部的控制。"},{id:"bian_ce",term:"鞭筴之威",pinyin:"biān cè zhī wēi",meaning:"鞭子与马鞭的威吓。鞭：皮鞭；筴：马鞭·竹鞭，读 cè；威：威吓·威压。鞭筴之威：后方鞭打的威吓——「后有鞭筴之威」指马后方受鞭打驱赶，是对马身体的暴力威胁。橛饰之患·鞭筴之威：前后夹击——前有嚼子约束，后有鞭打驱赶，马陷于前后夹击之中，「马之死者已过半矣」，是「治马」暴力的最终呈现。"},{id:"tao_zhe",term:"陶者",pinyin:"táo zhě",meaning:"制陶的工匠。陶者：制陶者·陶工，读 táo zhě——与「匠人」并举，以陶者治埴·匠人治木，类比伯乐治马，三者皆自称「善治」，皆是以人为强加于本然之性。"},{id:"zhi_zhi",term:"治埴",pinyin:"zhì zhí",meaning:"加工黏土（以人为技艺塑造黏土）。治：加工·处置；埴：黏土，读 zhí。治埴：加工黏土——「埴」是制陶的原料，本然之埴无规矩可言，陶者以「善治」强加规矩（圆者中规·方者中矩），正是「以人为易物之性」。"},{id:"zhong_gui_ju",term:"圆者中规·方者中矩",pinyin:"yuán zhě zhōng guī · fāng zhě zhōng jǔ",meaning:"圆的符合圆规·方的符合矩尺。圆者：圆形的；中：符合·切合，读 zhōng；规：圆规；方者：方形的；矩：矩尺·角尺。圆者中规·方者中矩：圆的合乎圆规·方的合乎矩尺——以规矩衡量埴的形状，是人为标准强加于黏土本然之性的具体形态。"},{id:"zhong_gou_sheng",term:"曲者中钩·直者应绳",pinyin:"qū zhě zhōng gōu · zhí zhě yìng shéng",meaning:"弯曲的符合钩尺·笔直的符合墨绳。曲者：弯曲的；中钩：符合钩尺；直者：笔直的；应绳：符合墨绳·墨线。曲者中钩·直者应绳：弯的合乎钩·直的合乎绳——与「圆者中规·方者中矩」并举，以钩绳衡量木材，同样是人为标准强加于木之本然。规矩钩绳：四种人为量度工具，喻仁义礼法等人为规范，是《马蹄》篇的核心批判意象。"},{id:"qi_yu",term:"岂欲",pinyin:"qǐ yù",meaning:"哪里想要·难道想要（反问·否定）。岂：哪里·难道；欲：想要。岂欲中规矩钩绳哉：哪里想要符合规矩钩绳呢——以反问否定「善治」的合理性：埴木之性本不欲中规矩，是人为强加，非本然之愿。"},{id:"zhong_he",term:"中",pinyin:"zhōng",meaning:"符合·切合（达到某种标准）。中：符合·切合，读 zhōng（去声）。中规矩钩绳：符合规矩钩绳的标准——「中」在此作动词，读 zhōng，非「中间」之中，是「以人为标准衡量本然」的关键动词。"},{id:"ci_yi",term:"此亦",pinyin:"cǐ yì",meaning:"这也是·这同样是（类比推论）。此亦：这也是——以「此亦」将伯乐治马·陶匠治埴木类比推论至「治天下者之过」，是本节的核心转折：从具体（马·埴·木）到抽象（天下），完成批判的升华。"},{id:"zhi_tianxia",term:"治·过",pinyin:"zhì · guò",meaning:"治理·过失（治理天下的过失）。治：治理，读 zhì；过：过失·错误。治天下者之过：治理天下者的过失——「治天下者之过」是本节的总结判断：伯乐治马·陶匠治埴木·匠人治木，皆是「善治」之名下对本然之性的摧残，正是治天下者（圣人·仁义礼法）之过的寓言化。"}],h=[{id:"mati2_s1",label:"吾意善治天下者不然",sentences:[["吾",{text:"意",glossary:"yi_buran"},"善治天下者",{text:"不然",glossary:"yi_buran"},"。"]]},{id:"mati2_s2",label:"彼民有常性……命曰天放",sentences:[["彼民有",{text:"常性",glossary:"chang_xing"},"，织而衣，耕而食，是谓",{text:"同德",glossary:"tong_de"},"。"],[{text:"一而不党",glossary:"yi_bu_dang"},"，",{text:"命曰天放",glossary:"tian_fang"},"。"]]},{id:"mati2_s3",label:"故至德之世……其视颠颠",sentences:[["故至德之世，",{text:"其行填填",glossary:"xing_tian"},"，",{text:"其视颠颠",glossary:"shi_dian"},"。"]]},{id:"mati2_s4",label:"当是时也……草木遂长",sentences:[[{text:"当是时也",glossary:"dang_shi"},"，",{text:"山无蹊隧",glossary:"xi_sui"},"，",{text:"泽无舟梁",glossary:"zhou_liang"},"；"],[{text:"万物群生",glossary:"qun_sheng"},"，",{text:"连属其乡",glossary:"lian_xiang"},"；"],[{text:"禽兽成群",glossary:"qun_sheng"},"，",{text:"草木遂长",glossary:"sui_zhang"},"。"]]},{id:"mati2_s5",label:"是故禽兽可系羁而游……鸟鹊之巢可攀援而窥",sentences:[["是故禽兽可",{text:"系羁而游",glossary:"xi_ji_you"},"，鸟鹊之巢可",{text:"攀援而窥",glossary:"pan_kui"},"。"]]},{id:"mati2_s6",label:"夫至德之世……恶乎知君子小人哉",sentences:[["夫至德之世，同与禽兽居，族与万物",{text:"并",glossary:"bing_ju"},"。"],[{text:"恶乎知",glossary:"wu_zhi"},"君子小人哉！"]]},{id:"mati2_s7",label:"同乎无知……素朴而民性得矣",sentences:[["同乎无知，其德不离；同乎无欲，是谓",{text:"素朴",glossary:"su_pu"},"。"],["素朴而民性得矣。"]]},{id:"mati2_s8",label:"及至圣人……而天下始分矣",sentences:[["及至圣人，",{text:"蹩躠为仁",glossary:"bie_xie"},"，",{text:"踶跂为义",glossary:"di_qi"},"，而天下",{text:"始疑",glossary:"shi_yi_fen"},"矣。"],[{text:"澶漫为乐",glossary:"chan_man"},"，",{text:"摘僻为礼",glossary:"zhai_pi"},"，而天下",{text:"始分",glossary:"shi_yi_fen"},"矣。"]]},{id:"mati2_s9",label:"故纯朴不残……孰应六律",sentences:[["故",{text:"纯朴不残",glossary:"chun_pu_bu_can"},"，孰为",{text:"牺尊",glossary:"xi_zun"},"！"],[{text:"白玉不毁",glossary:"bai_yu_gui_zhang"},"，孰为",{text:"珪璋",glossary:"bai_yu_gui_zhang"},"！"],[{text:"道德不废",glossary:"dao_de_bu_fei"},"，",{text:"安取仁义",glossary:"an_qu"},"！"],[{text:"性情不离",glossary:"xing_qing_bu_li"},"，",{text:"安用礼乐",glossary:"an_qu"},"！"],[{text:"五色不乱",glossary:"wu_se_cai"},"，孰为",{text:"文采",glossary:"wu_se_cai"},"！"],[{text:"五声不乱",glossary:"wu_sheng_lv"},"，孰",{text:"应六律",glossary:"wu_sheng_lv"},"！"]]}],y=[{id:"yi_buran",term:"意·不然",pinyin:"yì · bù rán",meaning:"以为·认为；不是这样（转折判断句式）。意：以为·认为，读 yì（动词）；不然：不是这样·并非如此。吾意善治天下者不然：我认为善于治理天下的人不是那样的——「吾意……不然」是本节的起首转折句，承接上节「此亦治天下者之过也」，以「不然」否定伯乐式的「善治」，引出至德之世的正面论述。"},{id:"chang_xing",term:"常性",pinyin:"cháng xìng",meaning:"本然常性（人天生固有的本然之性）。常：固有·本然；性：本性。彼民有常性：那些人民有本然的常性——「常性」是本节的核心概念，与《骈拇》篇「天下有常然」呼应，指织而衣·耕而食的本然生活方式，无需仁义礼法的外在规范。"},{id:"tong_de",term:"同德",pinyin:"tóng dé",meaning:"同于本然之德（共同处于本然德性之中）。同：共同·同一；德：本然之德。是谓同德：这叫做同德——织而衣·耕而食，各自顺应本然，共同处于德性之中，无需仁义的外在规定，自然而然地「同德」。"},{id:"yi_bu_dang",term:"一而不党",pinyin:"yī ér bù dǎng",meaning:"浑然一体而不结党分派。一：浑然一体·合一；不党：不结党·不分派，读 dǎng。一而不党：浑然合一而不分党派——至德之世，人与人之间浑然一体，无君子小人之分，无党派之争，是「同德」的社会形态。"},{id:"tian_fang",term:"命曰天放",pinyin:"mìng yuē tiān fàng",meaning:"称之为天然放任（顺天而放任本然）。命：称之为·命名；天放：天然放任·顺天放任。命曰天放：称之为天放——「天放」是至德之世的本然状态：顺天而放任，无人为干预，是本节最核心的概念之一，与「常性·同德」共同构成至德之世的三个关键词。"},{id:"xing_tian",term:"其行填填",pinyin:"qí xíng tián tián",meaning:"他们的行走安稳踏实。行：行走·举止；填填：安稳踏实的样子，读 tián tián（叠词）。其行填填：行走安稳踏实——描绘至德之世人的外在举止：无急迫·无焦虑，安然自得。"},{id:"shi_dian",term:"其视颠颠",pinyin:"qí shì diān diān",meaning:"他们的目光专注淡定。视：目光·眼神；颠颠：专注淡定·目光纯一的样子，读 diān diān（叠词）。其视颠颠：目光专注淡定——与「其行填填」并举，描绘至德之世人的内在神态：目光纯一，无旁骛·无机心。填填·颠颠：两组叠词，以音韵描绘本然状态的安稳与纯粹。"},{id:"dang_shi",term:"当是时也",pinyin:"dāng shì shí yě",meaning:"在那个时候（指至德之世）。当：在……时；是时：那个时候；也：语气词。当是时也：在那个时候——以「当是时也」引出至德之世的具体图景，是时间定语，标志从「定义」转入「描绘」。"},{id:"xi_sui",term:"山无蹊隧",pinyin:"shān wú xī suì",meaning:"山中没有小路与隧道（无人为开凿的道路）。蹊：小路·山间小径，读 xī；隧：隧道·山中通道，读 suì。山无蹊隧：山中没有人为开凿的小路与隧道——无人为改造自然，山保持本然形态。"},{id:"zhou_liang",term:"泽无舟梁",pinyin:"zé wú zhōu liáng",meaning:"水泽中没有船只与桥梁（无人为建造的交通设施）。泽：水泽·湖泽；舟：船只；梁：桥梁。泽无舟梁：水泽中没有船只与桥梁——与「山无蹊隧」并举，描绘至德之世无人为改造自然的本然状态：山水皆保持本然，无人为干预。"},{id:"qun_sheng",term:"万物群生·禽兽成群",pinyin:"wàn wù qún shēng · qín shòu chéng qún",meaning:"万物群聚生长·禽兽成群结队。群生：群聚生长；成群：成群结队。万物群生·禽兽成群：万物与禽兽皆按本然群聚——两句并举，描绘至德之世万物的本然群居状态，无人为干预，各依本性聚居。"},{id:"lian_xiang",term:"连属其乡",pinyin:"lián shǔ qí xiāng",meaning:"相互连属于各自的乡土（各依本然聚居）。连属：相互连属·相连；其乡：各自的乡土·栖息地。连属其乡：相互连属于各自的栖息地——万物各依本然聚居，无迁离·无流散，是本然秩序的描绘。"},{id:"sui_zhang",term:"草木遂长",pinyin:"cǎo mù suì zhǎng",meaning:"草木顺遂生长（按本然自由生长）。遂：顺遂·顺利，读 suì；长：生长，读 zhǎng。草木遂长：草木顺遂自由生长——无人为砍伐·修剪，草木按本然生长，与「万物群生·禽兽成群」共同构成至德之世的本然图景。"},{id:"xi_ji_you",term:"系羁而游",pinyin:"xì jī ér yóu",meaning:"用绳索牵引着一起游玩（人与禽兽亲密无间）。系：用绳系住·牵引，读 xì；羁：马笼头·绳索，读 jī；游：游玩·嬉戏。系羁而游：牵着绳索一起游玩——至德之世，人与禽兽亲密无间，可以牵着禽兽游玩，是人与自然本然和谐的具体描绘。"},{id:"pan_kui",term:"攀援而窥",pinyin:"pān yuán ér kuī",meaning:"攀爬上去窥看（人与鸟鹊亲密无间）。攀援：攀爬·攀登；窥：窥看·探看。攀援而窥：攀爬上去窥看鸟巢——至德之世，人可以攀上鸟鹊之巢窥看，鸟不惊飞，是人与自然本然亲密的极致描绘。系羁而游·攀援而窥：两个具体动作，以人与禽兽·鸟鹊的亲密互动，具象化「同与禽兽居·族与万物并」的至德之世。"},{id:"bing_ju",term:"并",pinyin:"bìng",meaning:"并列·并处（与万物并列共处）。并：并列·并处，读 bìng。族与万物并：与万物并列共处——「族」指同类·族群；「并」指并列共处。人与万物并列，无高下之分，是至德之世「同与禽兽居」的哲学表达。"},{id:"wu_zhi",term:"恶乎知",pinyin:"wū hū zhī",meaning:"从哪里知道·怎么会知道（反问·否定）。恶：何处·怎么，读 wū；乎：语气助词；知：知道·区分。恶乎知君子小人哉：怎么会知道谁是君子谁是小人呢——以反问否定君子·小人的区分：至德之世，人与禽兽并处，无名号之分，君子·小人的区别根本不存在。"},{id:"su_pu",term:"素朴",pinyin:"sù pǔ",meaning:"本然素朴（未经雕饰的本然状态）。素：本色·未染；朴：未雕·本然，读 pǔ。素朴：本然未经雕饰——「同乎无知·同乎无欲，是谓素朴」：与万物同于无知·无欲，这就叫素朴。素朴是至德之世的本然德性，与「纯朴」呼应，是《马蹄》篇的核心概念。"},{id:"bie_xie",term:"蹩躠为仁",pinyin:"bié xuē wéi rén",meaning:"跛行挣扎地去推行仁（费力勉强地为仁）。蹩躠：跛行·勉强挣扎的样子，读 bié xuē；为仁：推行仁·实践仁。蹩躠为仁：费力勉强地推行仁——以「蹩躠」（跛行挣扎）形容圣人推行仁的姿态：非本然流露，而是勉强费力，暗示仁是违背本然的人为强加。"},{id:"di_qi",term:"踶跂为义",pinyin:"dì qì wéi yì",meaning:"踮脚用力地去推行义（勉强努力地为义）。踶跂：踮脚用力·勉强努力的样子，读 dì qì；为义：推行义·实践义。踶跂为义：踮脚用力地推行义——与「蹩躠为仁」并举，以「蹩躠·踶跂」两个形容费力姿态的词，描绘圣人推行仁义的本质：勉强·费力·非本然，是对「及至圣人」的形象批判。"},{id:"shi_yi_fen",term:"始疑·始分",pinyin:"shǐ yí · shǐ fēn",meaning:"开始产生疑惑·开始分裂（本然被破坏的起点）。始：开始·才；疑：疑惑·迷失；分：分裂·分化。而天下始疑矣·而天下始分矣：天下才开始疑惑·天下才开始分裂——「始」字点出圣人是天下疑惑·分裂的起点，呼应《骈拇》篇「虞氏招仁义，天下始奔命」，圣人·仁义是本然失落的根源。"},{id:"chan_man",term:"澶漫为乐",pinyin:"chán màn wéi yuè",meaning:"放纵散漫地制作音乐（过度铺张地为乐）。澶漫：放纵散漫·过度铺张，读 chán màn；为乐：制作音乐·推行乐，读 yuè。澶漫为乐：放纵散漫地推行音乐——以「澶漫」形容圣人制乐的过度与散漫，是对「五声」本然的破坏。"},{id:"zhai_pi",term:"摘僻为礼",pinyin:"zhāi pì wéi lǐ",meaning:"挑剔偏执地制定礼仪（繁琐偏僻地为礼）。摘：挑剔·摘取；僻：偏执·偏僻，读 pì；为礼：制定礼仪·推行礼。摘僻为礼：挑剔偏执地推行礼——以「摘僻」形容圣人制礼的繁琐与偏执，是对本然性情的破坏。蹩躠·踶跂·澶漫·摘僻：四个形容词，皆描绘圣人推行仁义礼乐的勉强·费力·过度·偏执，共同构成「及至圣人」对本然的系统性破坏。"},{id:"chun_pu_bu_can",term:"纯朴不残",pinyin:"chún pǔ bù cán",meaning:"本然纯朴不被残害（本然之朴未遭破坏）。纯朴：本然纯朴；不残：不被残害·不被破坏。纯朴不残，孰为牺尊：本然纯朴不被残害，谁会去做牺尊——「纯朴不残·白玉不毁·道德不废·性情不离·五色不乱·五声不乱」六组「不……」构成排比反问，是本节的核心论证结构。"},{id:"xi_zun",term:"牺尊",pinyin:"xī zūn",meaning:"雕刻成牛形的祭祀酒器（以纯朴之木雕刻而成）。牺：雕刻成牛形；尊：酒器·祭器，读 zūn。牺尊：雕刻成牛形的祭祀酒器——以「牺尊」喻仁义礼乐：牺尊由纯朴之木雕刻而成，纯朴被残害才有牺尊；同理，本然被破坏才需要仁义礼乐。"},{id:"bai_yu_gui_zhang",term:"白玉不毁·珪璋",pinyin:"bái yù bù huǐ · guī zhāng",meaning:"白玉不被毁坏·珪璋（白玉被毁才成珪璋）。白玉不毁：白玉不被毁坏；珪：玉珪·礼器，读 guī；璋：玉璋·礼器，读 zhāng。白玉不毁，孰为珪璋：白玉不被毁坏，谁会去做珪璋——珪璋由白玉雕琢而成，白玉被毁才有珪璋；同理，本然被破坏才需要仁义礼乐。牺尊·珪璋：两种礼器，皆由本然之物（纯朴之木·白玉）被破坏后制成，喻仁义礼乐皆是本然被破坏的产物。"},{id:"dao_de_bu_fei",term:"道德不废",pinyin:"dào dé bù fèi",meaning:"道德不被废弃（本然道德完好存在）。道德：本然之道与德；不废：不被废弃·不被破坏。道德不废，安取仁义：道德不被废弃，哪里需要取用仁义——道德（本然）完好，仁义（人为）无从附着；道德被废，才需要仁义来填补。"},{id:"an_qu",term:"安取·安用",pinyin:"ān qǔ · ān yòng",meaning:"哪里需要取用·哪里需要使用（反问·否定必要性）。安：哪里·怎么（疑问副词）；取：取用；用：使用。安取仁义·安用礼乐：哪里需要取用仁义·哪里需要使用礼乐——以「安取·安用」反问，否定仁义礼乐的必要性：道德不废则无需仁义，性情不离则无需礼乐。"},{id:"xing_qing_bu_li",term:"性情不离",pinyin:"xìng qíng bù lí",meaning:"本性与真情不离散（性情保持本然完整）。性：本性；情：真情·本然之情；不离：不离散·不失落。性情不离，安用礼乐：本性与真情不离散，哪里需要使用礼乐——呼应《骈拇》篇「性情不离，安用礼乐」，性情完整则礼乐无用，礼乐是性情离散后的人为补救。"},{id:"wu_se_cai",term:"五色不乱·文采",pinyin:"wǔ sè bù luàn · wén cǎi",meaning:"五色不被扰乱·文采（本然色彩与人为文采）。五色：青·黄·赤·白·黑五种本然色彩；不乱：不被扰乱；文采：人为雕饰的色彩纹样。五色不乱，孰为文采：五色不被扰乱，谁会去做文采——五色本然完好，无需人为文采；文采是五色被扰乱后的人为修饰。"},{id:"wu_sheng_lv",term:"五声不乱·应六律",pinyin:"wǔ shēng bù luàn · yìng liù lǜ",meaning:"五声不被扰乱·应合六律（本然声音与人为音律）。五声：宫·商·角·徵·羽五种本然声音；不乱：不被扰乱；应：应合·符合；六律：古代音乐的六种律制（黄钟·太簇·姑洗·蕤宾·夷则·无射），读 liù lǜ。五声不乱，孰应六律：五声不被扰乱，谁会去应合六律——五声本然完好，无需六律规范；六律是五声被扰乱后的人为音律体系。纯朴·白玉·道德·性情·五色·五声：六组「本然」，对应牺尊·珪璋·仁义·礼乐·文采·六律六组「人为」，构成本节最完整的排比论证：本然完好则人为无用，人为之所以存在，正是本然被破坏的证明。"}],l=[{id:"mati3_s1",label:"夫残朴以为器……圣人之过也",sentences:[["夫",{text:"残朴以为器",glossary:"can_pu_qi"},"，",{text:"工匠之罪",glossary:"gongjian_zui"},"也；"],[{text:"毁道德",glossary:"hui_daode"},{text:"以为仁义",glossary:"yiwei_renyi"},"，",{text:"圣人之过",glossary:"shengren_guo3"},"也。"]]},{id:"mati3_s2",label:"夫马陆居则食草饮水……马知已此矣",sentences:[["夫马陆居则食草饮水，喜则",{text:"交颈相靡",glossary:"jiao_jing_mi"},"，怒则",{text:"分背相踢",glossary:"fen_bei_ti"},"。"],["马知已此矣！"]]},{id:"mati3_s3",label:"夫加之以衡扼……伯乐之罪也",sentences:[["夫",{text:"加之以衡扼",glossary:"heng_e"},"，",{text:"齐之以月题",glossary:"yue_ti"},"，"],["而马知",{text:"介倪",glossary:"jie_ni"},{text:"闉扼鸷曼",glossary:"yin_e_zhi_man"},{text:"诡衔窃辔",glossary:"gui_xian_qie_pei"},"。"],["故马之知而能",{text:"至盗者",glossary:"zhi_dao"},"，伯乐之罪也。"]]},{id:"mati3_s4",label:"夫赫胥氏之时……民能已此矣",sentences:[["夫",{text:"赫胥氏",glossary:"he_xu_shi"},"之时，民",{text:"居不知所为",glossary:"ju_xing_bu_zhi"},"，",{text:"行不知所之",glossary:"ju_xing_bu_zhi"},"，"],[{text:"含哺而熙",glossary:"han_bu_xi"},"，",{text:"鼓腹而游",glossary:"gu_fu_you"},"。"],[{text:"民能已此矣",glossary:"min_yi_ci"},"！"]]},{id:"mati3_s5",label:"及至圣人……不可止也",sentences:[["及至圣人，",{text:"屈折礼乐",glossary:"qu_zhe_li_yue"},"以",{text:"匡天下之形",glossary:"kuang_xing"},"，"],[{text:"县跂仁义",glossary:"xuan_qi_renyi"},"以",{text:"慰天下之心",glossary:"wei_xin"},"，"],["而民乃",{text:"始踶跂好知",glossary:"shi_di_qi_hao_zhi"},"，",{text:"争归于利",glossary:"zheng_gui_li"},"，",{text:"不可止也",glossary:"bu_ke_zhi"},"。"],["此亦",{text:"圣人之过也",glossary:"shengren_guo3"},"。"]]}],o=[{id:"can_pu_qi",term:"残朴以为器",pinyin:"cán pǔ yǐ wéi qì",meaning:"残害本然纯朴以制成器物。残：残害·破坏；朴：本然纯朴之木·未雕之材，读 pǔ；以为器：用来制成器物。残朴以为器：残害纯朴之材以制器——呼应上节「纯朴不残，孰为牺尊」，以「残朴为器」类比「毁道德为仁义」，构成本节的起首对举。"},{id:"gongjian_zui",term:"工匠之罪",pinyin:"gōng jiàng zhī zuì",meaning:"工匠的罪过（以人为技艺残害本然之罪）。工匠：制器的工匠；罪：罪过·过失。工匠之罪：工匠的罪过——「工匠之罪·圣人之过」对举：工匠残朴为器是罪，圣人毁道德为仁义是过，两者本质相同：以人为强加于本然。"},{id:"hui_daode",term:"毁道德",pinyin:"huǐ dào dé",meaning:"毁坏本然道德（破坏本然之道与德）。毁：毁坏·破坏；道德：本然之道与德（非仁义之道德）。毁道德：毁坏本然道德——以「毁」字点出圣人推行仁义的本质：不是建立，而是毁坏本然道德。"},{id:"yiwei_renyi",term:"以为仁义",pinyin:"yǐ wéi rén yì",meaning:"用来制造仁义（以毁道德为代价换取仁义）。以为：用来制造·用来做成；仁义：人为的仁义规范。毁道德以为仁义：毁坏道德用来制造仁义——与「残朴以为器」句式完全对应：朴→器 ＝ 道德→仁义，仁义是道德被毁后的人为产物，正如器是纯朴被残后的制成品。"},{id:"shengren_guo3",term:"圣人之过",pinyin:"shèng rén zhī guò",meaning:"圣人的过失（以人为规范破坏本然之过）。圣人：儒家推崇的圣人（此处为批判对象）；过：过失·错误，读 guò。圣人之过：圣人的过失——本节首尾两次出现「圣人之过」，构成首尾呼应的论证结构：开篇以「工匠之罪」类比引出，结尾以「此亦圣人之过也」总结，中间以马·赫胥氏两个寓言论证。"},{id:"jiao_jing_mi",term:"交颈相靡",pinyin:"jiāo jǐng xiāng mí",meaning:"相互交颈亲昵摩挲（马喜悦时的本然亲密行为）。交颈：相互交叉颈项；相靡：相互摩挲·亲昵，读 mí。交颈相靡：相互交颈摩挲——马喜悦时的本然表达，自然亲密，无需人为规范。"},{id:"fen_bei_ti",term:"分背相踢",pinyin:"fēn bèi xiāng tī",meaning:"分开背对相互踢踹（马愤怒时的本然表达）。分背：分开·背对；相踢：相互踢踹。分背相踢：背对相互踢踹——马愤怒时的本然表达，自然直接。交颈相靡·分背相踢：喜·怒两种本然情感的自然表达，无需仁义礼乐的规范，是「马知已此矣」的具体内容——马的本然知足于此，无需更多。"},{id:"heng_e",term:"加之以衡扼",pinyin:"jiā zhī yǐ héng è",meaning:"给马加上横木与颈轭（套上驾车的器具）。加：加上·套上；衡：横木·车衡，读 héng；扼：颈轭·套在马颈的器具，读 è。加之以衡扼：给马套上衡扼——以衡扼约束马颈，是伯乐「治马」的外在器具束缚，对应上节「连之以羁絷」。"},{id:"yue_ti",term:"齐之以月题",pinyin:"qí zhī yǐ yuè tí",meaning:"用月题来整齐马的额头（套上额饰约束马头）。齐：整齐·规范；月题：马额上的月形装饰·额带，读 yuè tí。齐之以月题：用月题整齐约束马头——以月题装饰·约束马的额头，是人为审美强加于马本然形态的具体器具。衡扼·月题：两种驾马器具，一束颈·一束额，从上到下约束马的本然，为后文马「知介倪闉扼鸷曼诡衔窃辔」的反抗埋下伏笔。"},{id:"jie_ni",term:"介倪",pinyin:"jiè ní",meaning:"斜视抗拒（马被束缚后产生的抵抗眼神）。介倪：斜视·侧目抗拒，读 jiè ní——马被衡扼·月题束缚后，开始以斜视表达抗拒，是本然被压制后反抗的第一个表现。"},{id:"yin_e_zhi_man",term:"闉扼鸷曼",pinyin:"yīn è zhì màn",meaning:"弓背抵扼·凶猛挣扎（马被束缚后的激烈反抗）。闉：弓背·拱背抵抗，读 yīn；扼：抵扼·抗拒颈轭；鸷：凶猛·猛烈，读 zhì；曼：蔓延·挣扎不止。闉扼鸷曼：弓背抵扼·凶猛挣扎——马被束缚后的激烈身体反抗，从斜视（介倪）升级为身体对抗。"},{id:"gui_xian_qie_pei",term:"诡衔窃辔",pinyin:"guǐ xián qiè pèi",meaning:"吐出嚼子·偷脱缰绳（马被束缚后的狡黠逃脱）。诡：诡计·狡黠，读 guǐ；衔：马嚼子·口中衔铁；窃：偷偷·暗中；辔：缰绳，读 pèi。诡衔窃辔：吐出嚼子·偷脱缰绳——马被束缚后学会狡黠逃脱，从身体反抗（闉扼鸷曼）升级为智巧逃脱。介倪·闉扼鸷曼·诡衔窃辔：三组递进——斜视抗拒→身体反抗→智巧逃脱，描绘马被束缚后「知」的堕落过程：本然之知（食草饮水·交颈相靡）被人为束缚逼成「盗者之知」（诡衔窃辔）。"},{id:"zhi_dao",term:"至盗者",pinyin:"zhì dào zhě",meaning:"达到盗的程度（马的知被逼成盗者之知）。至：达到·至于；盗：盗窃·狡黠逃脱；者：……的程度。马之知而能至盗者：马的知竟然达到盗的程度——「至盗」是本节马的寓言的核心判断：伯乐以衡扼·月题束缚马，逼使马从本然之知（食草饮水）堕落为盗者之知（诡衔窃辔），故「伯乐之罪也」。类比：圣人以礼乐仁义束缚民，逼使民从本然（含哺而熙·鼓腹而游）堕落为「踶跂好知·争归于利」。"},{id:"he_xu_shi",term:"赫胥氏",pinyin:"hè xū shì",meaning:"传说中上古的帝王（本然之世的象征）。赫胥氏：读 hè xū shì，传说中上古帝王，其时民风淳朴，无知无欲——与《骈拇》篇「虞氏」对举：虞氏（舜）是「招仁义·天下始奔命」的起点，赫胥氏是「天放·素朴」的本然之世的象征，呼应上节「至德之世」。"},{id:"ju_xing_bu_zhi",term:"居不知所为·行不知所之",pinyin:"jū bù zhī suǒ wéi · xíng bù zhī suǒ zhī",meaning:"居处时不知道该做什么·行走时不知道要去哪里（本然无目的·无机心）。居：居处·静处；不知所为：不知道该做什么；行：行走；不知所之：不知道要去哪里。居不知所为·行不知所之：居处无目的·行走无方向——非愚昧，而是本然无机心·无目的的自在状态，是「天放」的人的具体描绘。"},{id:"han_bu_xi",term:"含哺而熙",pinyin:"hán bǔ ér xī",meaning:"口含食物嬉戏玩耍（饮食自然·无忧无虑）。含：口含；哺：食物·口中之食，读 bǔ；熙：嬉戏·欢乐，读 xī。含哺而熙：口含食物嬉戏——描绘赫胥氏之时民的本然饮食状态：如婴儿般口含食物嬉戏，无忧无虑，自然自在。"},{id:"gu_fu_you",term:"鼓腹而游",pinyin:"gǔ fù ér yóu",meaning:"拍着肚子悠游自在（饱食后自在游荡）。鼓腹：拍打肚子·鼓起肚子（饱食之状）；游：悠游·游荡。鼓腹而游：拍着肚子悠游——饱食后无目的地悠游，是本然满足·无欲无求的状态。含哺而熙·鼓腹而游：两个具体动作，以饮食·游玩的本然状态，描绘赫胥氏之时「天放」的人，呼应上节「其行填填·其视颠颠」，是至德之世的人间版图景。"},{id:"min_yi_ci",term:"民能已此矣",pinyin:"mín néng yǐ cǐ yǐ",meaning:"民的本然能力已足于此了（本然知足·无需更多）。能：能力·本然所能；已此：已足于此·仅此而已；矣：语气词（感叹）。民能已此矣：民的本然已足于此——呼应上节「马知已此矣」，两个「已此矣」并举：马的本然知足于食草饮水·交颈相靡，民的本然知足于含哺而熙·鼓腹而游，皆无需外在干预。"},{id:"qu_zhe_li_yue",term:"屈折礼乐",pinyin:"qū zhé lǐ yuè",meaning:"强行扭曲礼乐以规范天下（以礼乐强制塑造人的形态）。屈折：强行弯曲·扭曲，读 qū zhé；礼乐：礼仪与音乐（人为规范）。屈折礼乐：强行扭曲礼乐——以「屈折」描绘圣人推行礼乐的姿态：强行弯曲·扭曲，非自然流露，是对本然的强制塑造，呼应上节「蹩躠为仁·踶跂为义」。"},{id:"kuang_xing",term:"匡天下之形",pinyin:"kuāng tiān xià zhī xíng",meaning:"矫正天下人的形态（以礼乐规范人的外在行为）。匡：矫正·规范，读 kuāng；形：形态·外在行为。匡天下之形：矫正天下人的外在形态——以礼乐「匡形」，是对人外在行为的强制规范，对应伯乐以衡扼·月题「齐马」。"},{id:"xuan_qi_renyi",term:"县跂仁义",pinyin:"xuán qì rén yì",meaning:"悬挂高举仁义以诱导天下（以仁义为诱饵吊引人心）。县：通「悬」，悬挂·高举，读 xuán；跂：踮脚企望·引颈期盼，读 qì。县跂仁义：悬挂高举仁义——以「县跂」描绘圣人推行仁义的姿态：将仁义高悬如诱饵，使天下人踮脚企望，是对人内在之心的诱导与操控。"},{id:"wei_xin",term:"慰天下之心",pinyin:"wèi tiān xià zhī xīn",meaning:"安慰天下人的心（以仁义填补·安抚人心）。慰：安慰·抚慰；心：内心·本然之心。慰天下之心：安慰天下人的心——以仁义「慰心」，是对人内在之心的操控，对应礼乐「匡形」。屈折礼乐匡形·县跂仁义慰心：外（形）·内（心）两层并举——礼乐规范外在形态，仁义操控内在之心，圣人以内外两层全面控制天下，是伯乐「加衡扼·齐月题」的人间版。"},{id:"shi_di_qi_hao_zhi",term:"始踶跂好知",pinyin:"shǐ dì qì hào zhī",meaning:"开始踮脚用力·好用智巧（本然被破坏后的异化）。始：开始·才；踶跂：踮脚用力·勉强挣扎，读 dì qì；好知：喜好智巧·争用机心，读 hào zhī。始踶跂好知：开始踮脚用力·喜好智巧——民被礼乐仁义束缚后，从本然（含哺而熙·鼓腹而游）堕落为「踶跂好知」，呼应上节「蹩躠为仁·踶跂为义」：圣人踶跂为义，民也被逼得踶跂好知，圣人的「治」造成民的异化。"},{id:"zheng_gui_li",term:"争归于利",pinyin:"zhēng guī yú lì",meaning:"争相奔向利益（本然被破坏后的逐利堕落）。争：争相·竞争；归：归向·奔向；利：利益·名利。争归于利：争相奔向利益——民被圣人以礼乐仁义束缚后，从本然的无欲（鼓腹而游）堕落为争利，呼应《骈拇》篇「天下奔命于仁义」·「小人以身殉利」。"},{id:"bu_ke_zhi",term:"不可止也",pinyin:"bù kě zhǐ yě",meaning:"不可遏止（一旦开始争利便无法停止）。止：遏止·停止。不可止也：不可遏止——以「不可止也」描绘民争归于利的不可逆性：圣人以礼乐仁义「治」天下，一旦激发民的踶跂好知·争归于利，便如洪水决堤，不可遏止，是「圣人之过」的最终后果。"}];return(q,i)=>{const p=a("DaoReadingPrelude"),r=a("DaoTextReading"),s=a("DaoKeywordCards"),g=a("DaoLineGuide");return u(),x("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·马蹄",tabindex:"-1"},[t("庄子·马蹄 "),n("a",{class:"header-anchor",href:"#庄子·马蹄","aria-label":'Permalink to "庄子·马蹄"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[t("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"《马蹄》是《庄子》外篇的第二篇，紧承《骈拇》之后。")]),n("p",null,"《骈拇》说：仁义聪明，是骈枝——侈于德。《马蹄》说：伯乐善治马，圣人善治天下——这是罪，这是过。"),n("p",null,"两篇，是同一个命题的两种推进：《骈拇》批判的是「什么」——仁义；《马蹄》批判的是「谁」——善治者·伯乐·圣人。")],-1)),e(p,{title:"从马之真性到含哺而熙，理解庄子对「善治」的批判",summary:"《马蹄》用伯乐治马作比喻，展开外篇「善治」批判的第二个命题：马之真性完整自足，及至伯乐「我善治马」，烧剔刻雒、羁絷皂栈——马之死者过半；民之常性素朴天放，及至圣人屈折礼乐、县跂仁义——天下始疑始分、争归于利不可止。残朴为器，工匠之罪；毁道德为仁义，圣人之过。",points:[{label:"先看",text:"顺着马之真性、至德之世、圣人之过三段，辨认每一次「及至」的转折。"},{label:"再问",text:"庄子说「圣人之过」，是否否定了一切文明？"},{label:"最后",text:"「含哺而熙，鼓腹而游」——你的本性，还需要被「善治」吗？"}],hint:"三次「及至」（及至伯乐·及至圣人·及至圣人），是《马蹄》的叙事骨架——每一次「及至」，都是一次本然状态的终结。"}),i[3]||(i[3]=n("h2",{id:"一、马之真性与善治之过",tabindex:"-1"},[t("一、马之真性与善治之过 "),n("a",{class:"header-anchor",href:"#一、马之真性与善治之过","aria-label":'Permalink to "一、马之真性与善治之过"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[t("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(r,{sections:d,glossary:m,"default-mode":"classic","aria-label":"马蹄·马之真性 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[t("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"践",pinyin:["jiàn"],meaning:"踩踏。蹄可以践霜雪：马蹄能够踏着霜雪行走。"},{term:"御",pinyin:["yù"],meaning:"抵御。毛可以御风寒：马毛能够抵挡风寒。"},{term:"齕",pinyin:["hé"],meaning:"啃咬。齕草饮水：啃食青草，饮用清水。"},{term:"翘足而陆",pinyin:["qiáo","zú","ér","lù"],meaning:"抬足跳跃。陆通“踛”，指跳跃腾跃。"},{term:"义台路寝",pinyin:["yì","tái","lù","qǐn"],meaning:"华美的高台和宽大的正寝。"},{term:"无所用之",pinyin:["wú","suǒ","yòng","zhī"],meaning:"对马没有用处。之：指义台路寝。"},{term:"善",pinyin:["shàn"],meaning:"擅长、善于。“我善治马”是伯乐自称精于驯治。"},{term:"烧之",pinyin:["shāo","zhī"],meaning:"用火烧灼马。之：指马。"},{term:"剔之",pinyin:["tī","zhī"],meaning:"剔除、修剪马毛。之：指马。"},{term:"刻之",pinyin:["kè","zhī"],meaning:"刻削马蹄。之：指马蹄。"},{term:"雒之",pinyin:["luò","zhī"],meaning:"烙印马。雒通“烙”，给马打上印记。"},{term:"连之",pinyin:["lián","zhī"],meaning:"把马连缀、束缚起来。"},{term:"羁絷",pinyin:["jī","zhí"],meaning:"马络头和绊马索，用来控制马。"},{term:"编之",pinyin:["biān","zhī"],meaning:"编结、约束马。"},{term:"皂栈",pinyin:["zào","zhàn"],meaning:"马槽和马棚，用来圈养马。"},{term:"十二三矣",pinyin:["shí","èr","sān","yǐ"],meaning:"十分之二三。已有约十分之二三的马死去。"},{term:"饥之",pinyin:["jī","zhī"],meaning:"使马饥饿。饥：使动用法。"},{term:"渴之",pinyin:["kě","zhī"],meaning:"使马口渴。渴：使动用法。"},{term:"驰之",pinyin:["chí","zhī"],meaning:"使马奔驰。驰：使动用法。"},{term:"骤之",pinyin:["zhòu","zhī"],meaning:"使马急跑。骤：快速奔跑。"},{term:"整之",pinyin:["zhěng","zhī"],meaning:"使马整齐。"},{term:"齐之",pinyin:["qí","zhī"],meaning:"使马划一。"},{term:"橛饰之患",pinyin:["jué","shì","zhī","huàn"],meaning:"马嚼子和装饰带来的祸患。"},{term:"鞭筴之威",pinyin:["biān","cè","zhī","wēi"],meaning:"鞭打与驱赶的威势。筴通“策”，指马鞭。"},{term:"陶者",pinyin:["táo","zhě"],meaning:"制陶的人。"},{term:"治埴",pinyin:["zhì","zhí"],meaning:"加工黏土。埴：黏土。"},{term:"中规",pinyin:["zhòng","guī"],meaning:"符合圆规。中：符合，读 zhòng。"},{term:"中矩",pinyin:["zhòng","jǔ"],meaning:"符合矩尺。中：符合，读 zhòng。"},{term:"中钩",pinyin:["zhòng","gōu"],meaning:"符合曲尺。中：符合，读 zhòng。"},{term:"应绳",pinyin:["yìng","shéng"],meaning:"合乎墨线。"},{term:"岂欲",pinyin:["qǐ","yù"],meaning:"难道想要、哪里愿意。"},{term:"中",pinyin:["zhòng"],meaning:"符合、合乎标准。"},{term:"此亦",pinyin:["cǐ","yì"],meaning:"这也同样是。"},{term:"治",pinyin:["zhì"],meaning:"治理、整治。治天下：以人为标准管理天下。"},{term:"过",pinyin:["guò"],meaning:"过失、错误。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[t("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(g,{title:"马之真性，完整自足——及至伯乐，一切开始改变",subtitle:"用人的标准来「善治」马——这本身，就是问题的起点。",lines:[{text:"马，蹄可以践霜雪，毛可以御风寒。齕草饮水，翘足而陆，此马之真性也。虽有义台路寝，无所用之。",tone:"真性",guide:"《马蹄》开篇，庄子用极简洁的笔墨，描绘了马的真性——四句话，四个维度：蹄可以践霜雪（马蹄，天生就能踩踏霜雪）、毛可以御风寒（马毛，天生就能抵御风寒）、齕草饮水（啃草喝水，自给自足）、翘足而陆（昂首翘足，纵跳腾跃）。此马之真性也——这四句，描绘的是马在自然状态下的完整生命——不需要任何人来「帮助」它，不需要任何工具来「改善」它——它本来就是完整的、自足的。紧接着，庄子轻轻补了一句：「虽有义台路寝，无所用之。」义台路寝——华美的台榭、宏伟的宫室——这是人类文明的成就，是人类认为「好」的东西——但对马来说，无所用之——没有任何用处。这一句，看似轻描淡写，实则是全篇最深的预设：人类用「好」的标准来衡量马——但马有自己的「好」——马的「好」，是践霜雪、御风寒、齕草饮水、翘足而陆——不是义台路寝。用人的标准来「善治」马——这本身，就是问题的起点。"},{text:"及至伯乐，曰：我善治马。烧之，剔之，刻之，雒之。连之以羁絷，编之以皂栈，马之死者十二三矣！",tone:"伯乐",guide:"「及至伯乐」——等到伯乐出现——这两个字，是《马蹄》全篇的第一个转折标志：马的真性，本来是完整的——「及至伯乐」——一切开始改变。「我善治马」——注意：伯乐说的是「善」治——不是恶意的，不是破坏性的——是「善意的治」，是「好的治」。庄子要批判的，不是恶意的破坏，而是善意的治理——正是这个「善」，才是最深的问题所在。伯乐的「善治」，分两个阶段展开——第一阶段·改造身体：烧（用火烙烫马蹄）、剔（剃除马毛）、刻（刻削蹄甲）、雒（烙印记号）——每一个动作，都直接对应马的一项真性。再加上羁絷皂栈——络头绊索、马槽马棚——束缚自由，圈养空间——马之死者十二三矣——还没有开始正式「使用」，马就已经死了十分之二三。"},{text:"饥之渴之，驰之骤之，整之齐之，前有橛饰之患，而后有鞭筴之威，而马之死者已过半矣！",tone:"过半",guide:"第二阶段·训练使用：饥之渴之（用饥渴控制马）、驰之骤之（强制奔跑训练）、整之齐之（训练整齐队列）、前有橛饰束缚、后有鞭筴威胁——马之死者已过半矣——马，已经死了超过一半。两个阶段，两个数字——从十二三，到过半——「善治」越深入，死亡越多。这不是意外，这是必然：马蹄，天生可以践霜雪——烧之；马毛，天生可以御风寒——剔之；自由奔跑——驰之骤之；自然栖息——编之以皂栈。马的每一项真性，都有一项「善治」与之对应——每一项「善治」，都是对那项真性的直接破坏。伯乐不是在「治」马——伯乐是在把马，从「马」变成「工具」。"},{text:"夫埴木之性，岂欲中规矩钩绳哉！然且世世称之曰：伯乐善治马，而陶匠善治埴木。此亦治天下者之过也。",tone:"反问",guide:"庄子把伯乐的逻辑，推广到陶匠与木匠——陶匠「我善治埴」：圆的符合圆规，方的符合方尺——把黏土，做成规矩的形状；木匠「我善治木」：弯曲的符合曲尺，笔直的符合墨线——把木材，做成规整的形状。三者，是同一个逻辑：都是用外在的标准（规矩钩绳），来改造对象的天然状态。庄子的反问，是全段的核心：「夫埴木之性，岂欲中规矩钩绳哉！」黏土与木材的本性，难道想要符合规矩钩绳的标准吗？本性，从来不「欲」被外在标准所规范——「欲」，是外在强加的，不是本性自然的。然而——「然且世世称之曰」——世世代代，都在称赞他们「善治」。这是第一段最深的一击：称赞「善治」，就是在确立「善治」的合法性——就是在告诉天下：改造本性，是对的；用外在标准规范本性，是好的。「此亦治天下者之过也」——这，也是治天下者的过失。「亦」——也——暗示了一个未说出口的前提：治天下者，还有更多的过——称赞善治，只是其中之一。"}]}),i[7]||(i[7]=n("h2",{id:"二、至德之世",tabindex:"-1"},[t("二、至德之世 "),n("a",{class:"header-anchor",href:"#二、至德之世","aria-label":'Permalink to "二、至德之世"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[t("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),e(r,{sections:h,glossary:y,"default-mode":"classic","aria-label":"马蹄·至德之世 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[t("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"意",pinyin:["yì"],meaning:"认为、料想。吾意：我认为。"},{term:"不然",pinyin:["bù","rán"],meaning:"不是这样。承接上段，否定伯乐式的“善治”。"},{term:"常性",pinyin:["cháng","xìng"],meaning:"恒常、本然的性情。民有常性：百姓有自然固有的生活与性情。"},{term:"同德",pinyin:["tóng","dé"],meaning:"共同处于本真之德。各循本性而生活，便是同德。"},{term:"一而不党",pinyin:["yī","ér","bù","dǎng"],meaning:"浑然一体而不结党分派。"},{term:"天放",pinyin:["tiān","fàng"],meaning:"顺应天然，任其自放，不以人为标准强制改变本性。"},{term:"至德之世",pinyin:["zhì","dé","zhī","shì"],meaning:"至德充分呈现的时代，人的性情保持本真。"},{term:"填填",pinyin:["tián","tián"],meaning:"安稳厚重的样子。其行填填：行止安定，不急迫奔竞。"},{term:"颠颠",pinyin:["diān","diān"],meaning:"专一纯真的样子。其视颠颠：目光不被外物牵引。"},{term:"蹊隧",pinyin:["xī","suì"],meaning:"山间小路和隧道。指人为开凿的通道。"},{term:"舟梁",pinyin:["zhōu","liáng"],meaning:"船和桥梁，指人为设置的水上交通设施。"},{term:"群生",pinyin:["qún","shēng"],meaning:"群聚而生。万物各循其类生息。"},{term:"连属其乡",pinyin:["lián","shǔ","qí","xiāng"],meaning:"相连依附于各自的乡土、栖息之处。"},{term:"成群",pinyin:["chéng","qún"],meaning:"成群结队。禽兽按其本性聚居。"},{term:"遂长",pinyin:["suì","zhǎng"],meaning:"顺遂地生长。遂：顺利、自然。"},{term:"系羁而游",pinyin:["xì","jī","ér","yóu"],meaning:"系着绳索一同游走。人与禽兽之间没有恐惧和伤害。"},{term:"攀援而窥",pinyin:["pān","yuán","ér","kuī"],meaning:"攀爬上去窥看鸟鹊之巢。"},{term:"并",pinyin:["bìng"],meaning:"并处、并列。族与万物并：人与万物平等共处。"},{term:"恶乎知",pinyin:["wū","hū","zhī"],meaning:"怎么知道、从哪里知道。反问君子小人的区分。"},{term:"素朴",pinyin:["sù","pǔ"],meaning:"未经染饰和雕琢的本真状态。"},{term:"蹩躠为仁",pinyin:["bié","sà","wéi","rén"],meaning:"竭尽心力般地推行仁。蹩躠：用力、费力的样子。"},{term:"踶跂为义",pinyin:["zhì","qí","wéi","yì"],meaning:"踮脚用力般地推行义。踶跂：努力企及的样子。"},{term:"始疑",pinyin:["shǐ","yí"],meaning:"开始疑惑。圣人推行仁义后，天下由安定转入疑惑。"},{term:"澶漫为乐",pinyin:["chán","màn","wéi","yuè"],meaning:"放纵铺张地推行音乐。澶漫：流溢而无所节制。"},{term:"摘僻为礼",pinyin:["zhāi","pì","wéi","lǐ"],meaning:"以琐碎偏执的方式推行礼。摘僻：挑剔偏执。"},{term:"始分",pinyin:["shǐ","fēn"],meaning:"开始分裂、分化。礼乐繁作后，天下出现人为分别。"},{term:"纯朴不残",pinyin:["chún","pǔ","bù","cán"],meaning:"纯朴不被残害。若本然之朴完整，便无需雕成牺尊。"},{term:"牺尊",pinyin:["xī","zūn"],meaning:"雕成牛形的祭祀酒器。"},{term:"白玉不毁",pinyin:["bái","yù","bù","huǐ"],meaning:"白玉不被雕琢毁损。"},{term:"珪璋",pinyin:["guī","zhāng"],meaning:"古代玉制礼器。珪为玉圭，璋为半圭形玉器。"},{term:"道德不废",pinyin:["dào","dé","bù","fèi"],meaning:"本然的道与德不被废弃、损伤。"},{term:"安取",pinyin:["ān","qǔ"],meaning:"哪里需要取用。道德完整，便无需取用仁义。"},{term:"性情不离",pinyin:["xìng","qíng","bù","lí"],meaning:"本性与真情不离散、不失落。"},{term:"安用",pinyin:["ān","yòng"],meaning:"哪里需要使用。性情完整，便无需使用礼乐。"},{term:"五色不乱",pinyin:["wǔ","sè","bù","luàn"],meaning:"五种基本色不被人为扰乱。"},{term:"文采",pinyin:["wén","cǎi"],meaning:"人为装饰出的色彩与纹样。"},{term:"五声不乱",pinyin:["wǔ","shēng","bù","luàn"],meaning:"五种基本音不被人为扰乱。"},{term:"应六律",pinyin:["yìng","liù","lǜ"],meaning:"应合六律。应：符合；六律：古代音律中的六个阳律。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[t("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(g,{title:"天放·素朴——民性得矣",subtitle:"天放，是让本性自然流淌，不用任何外在标准来引导它、规范它、「改善」它。",lines:[{text:"吾意善治天下者不然。彼民有常性，织而衣，耕而食，是谓同德。一而不党，命曰天放。",tone:"天放",guide:"第一段批判了伯乐、陶匠、匠人的「善治」，第二段庄子以第一人称转入正论——「吾意」——依我看——真正善于治理天下的，不是那样做的。这一句，是第二段的总纲。庄子不是在说「不治」，而是在说「不那样治」——那么，真正的「善治天下」，是什么样的？民有常性——百姓，有自己恒常的本性——织而衣，耕而食——织布而穿衣，耕田而饮食——自给自足，不依赖任何外在的制度或规范。是谓同德——这，叫做「同德」。一而不党，命曰天放——浑然一体，不结党，不分派——没有「我们」与「他们」，没有派系，没有对立——这，称之为「天放」。「天放」，是《马蹄》全篇最重要的概念：不是放纵，不是无序——而是天然地放任本性自由生长，不加干涉，不加规范，不加「善治」。"},{text:"故至德之世，其行填填，其视颠颠。……禽兽可系羁而游，鸟鹊之巢可攀援而窥。",tone:"至德",guide:"庄子由「天放」的定义，展开至德之世的具体图景——其行填填，其视颠颠——两个叠词，描绘的是那个时代的人：行走，安稳踏实——不慌张，不急迫，不为任何目的奔命；目光，专注直视——不左顾右盼，不觊觎，不比较。这两个叠词，描绘的是一种内在的安定——因为本性没有被扰动，所以安定。接下来六个短句，描绘至德之世的自然状态：山无蹊隧（山中没有人工开凿的道路与隧道——人，不需要征服山）、泽无舟梁（水泽中没有船只与桥梁——人，不需要征服水）、万物群生连属其乡、禽兽成群草木遂长——没有人去「管理」它们，它们反而更好。然后是至德之世最动人的两个细节——禽兽可系羁而游（禽兽，可以用绳索牵着一起游玩——不是因为禽兽被驯服了，而是因为人与禽兽之间，没有恐惧，没有对立）、鸟鹊之巢可攀援而窥（鸟鹊的巢，可以攀爬上去探看——不是因为鸟鹊失去了警觉，而是因为人与鸟鹊之间，没有威胁，没有伤害）。这两个细节，描绘的不是人统治自然，而是人与自然之间，那种本然的亲密与信任——一旦人开始「善治」，它就消失了。"},{text:"同乎无知，其德不离；同乎无欲，是谓素朴。素朴而民性得矣。",tone:"素朴",guide:"庄子将图景收束，深入到至德之世的内在本质——同与禽兽居，族与万物并（与禽兽同居，与万物并列——不是说人退化为动物，而是说：人，没有把自己凌驾于万物之上）。恶乎知君子小人哉（至德之世，没有君子小人之分——不是因为所有人都一样，而是因为没有人用「君子小人」这套标准来衡量人——这套标准，本身就是「善治」的产物）。同乎无知，其德不离——同样处于无知的状态——这里的「无知」，不是愚昧，不是蒙昧——而是无机心之知——没有那种算计的、比较的、追名逐利的「知」——本真之德，不离散，不失去。同乎无欲，是谓素朴——同样处于无欲的状态——不是没有感受，不是麻木——而是无贪欲——没有那种占有的、攀比的、永不满足的「欲」——这，叫做素朴。「素朴」——素：未染色的丝——天然的颜色；朴：未加工的木——天然的形状——素朴，就是未经雕琢的自然本真状态——没有被仁义染色，没有被礼乐加工——保持着天然的颜色与形状。素朴而民性得矣——保持素朴，百姓的本性就得以保全。"},{text:"故纯朴不残，孰为牺尊！白玉不毁，孰为珪璋！道德不废，安取仁义！性情不离，安用礼乐！五色不乱，孰为文采！五声不乱，孰应六律！",tone:"六反问",guide:"六句排比，六个反问，是《马蹄》全篇最精彩的段落——结构完全一致：本然状态不被破坏 → 哪里需要人工产物？纯朴不残，孰为牺尊（浑然完整的木材，如果不被破坏，谁会去雕刻成牺尊？牺尊越精美，意味着纯朴被残得越深）；白玉不毁，孰为珪璋；道德不废，安取仁义（这是六句中最核心的一句：道德，如果不被废弃破坏——哪里需要取用仁义？仁义，是道德被废弃之后的替代品——有了仁义，就意味着道德已经废弃）；性情不离，安用礼乐；五色不乱，孰为文采；五声不乱，孰应六律。六句，共同指向一个逻辑：本然状态（完整·自足·无需外物）→ 被破坏 → 人工产物（补救·替代·外在标准）→ 被称赞为「善」→ 本然状态，永远消失。人工产物越精美，意味着本然状态被破坏得越彻底——牺尊越精美，纯朴被残得越深；仁义越完善，道德被废得越彻底。这是《马蹄》对文明最深的批判逻辑：文明的每一项成就，都是以本然状态的破坏为代价的——成就越高，代价越大。"}]}),i[11]||(i[11]=n("h2",{id:"三、圣人之过",tabindex:"-1"},[t("三、圣人之过 "),n("a",{class:"header-anchor",href:"#三、圣人之过","aria-label":'Permalink to "三、圣人之过"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[t("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),e(r,{sections:l,glossary:o,"default-mode":"classic","aria-label":"马蹄·圣人之过 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[t("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"残朴以为器",pinyin:["cán","pǔ","yǐ","wéi","qì"],meaning:"残：残损、破坏；朴：未加工的原木。破坏原木来制作器具。"},{term:"工匠之罪",pinyin:["gōng","jiàng","zhī","zuì"],meaning:"工匠的罪过。"},{term:"毁道德",pinyin:["huǐ","dào","dé"],meaning:"毁坏本然的道与德。这里不是建立仁义，而是先破坏道德。"},{term:"以为仁义",pinyin:["yǐ","wéi","rén","yì"],meaning:"拿来制作仁义，以毁坏道德为代价建立人为规范。"},{term:"圣人之过",pinyin:["shèng","rén","zhī","guò"],meaning:"圣人的过失。"},{term:"交颈相靡",pinyin:["jiāo","jǐng","xiāng","mí"],meaning:"交颈：颈部相交；靡：依偎、摩挲。高兴时互相依偎摩挲。"},{term:"分背相踢",pinyin:["fēn","bèi","xiāng","tī"],meaning:"分背：背对背分开；踢：踢踹。愤怒时背对背互相踢踹。"},{term:"衡扼",pinyin:["héng","è"],meaning:"衡：车衡，驾车的横木；扼：套在马颈上的轭。"},{term:"月题",pinyin:["yuè","tí"],meaning:"马额头上的月形装饰（马络头上的饰件）。"},{term:"介倪",pinyin:["jiè","ní"],meaning:"斜眼侧视（表示不驯服）。"},{term:"闉扼",pinyin:["yīn","è"],meaning:"弯曲身体抵抗颈轭。"},{term:"鸷曼",pinyin:["zhì","màn"],meaning:"凶猛抵触、拖延拖拽。"},{term:"诡衔",pinyin:["guǐ","xián"],meaning:"用诡诈的方式对付嚼子（吐衔）。"},{term:"窃辔",pinyin:["qiè","pèi"],meaning:"辔：缰绳。暗中咬断缰绳。"},{term:"至盗者",pinyin:["zhì","dào","zhě"],meaning:"达到像盗贼一样的程度。马被强制治理后，反而发展出诡诈逃脱之知。"},{term:"赫胥氏",pinyin:["hè","xū","shì"],meaning:"传说中上古时代的帝王，象征最本然的时代。"},{term:"居不知所为",pinyin:["jū","bù","zhī","suǒ","wéi"],meaning:"居处时不知要做什么，强调无所强为、无机心，不是迷失。"},{term:"行不知所之",pinyin:["xíng","bù","zhī","suǒ","zhī"],meaning:"行走时不知要往哪里去，强调任其自然，不以外在目标驱迫。"},{term:"含哺而熙",pinyin:["hán","bǔ","ér","xī"],meaning:"含哺：口含食物；熙：嬉戏、欢乐。口含食物嬉戏玩乐。"},{term:"鼓腹而游",pinyin:["gǔ","fù","ér","yóu"],meaning:"鼓腹：拍打肚子（吃饱的满足感）。拍着肚子悠游自在。"},{term:"民能已此矣",pinyin:["mín","néng","yǐ","cǐ","yǐ"],meaning:"百姓的本然能力做到这样就足够了。已此：止于此、仅此而已。"},{term:"屈折礼乐",pinyin:["qū","zhé","lǐ","yuè"],meaning:"屈折：扭曲、强迫。强行用礼乐扭曲天下人的形体与行为。"},{term:"匡天下之形",pinyin:["kuāng","tiān","xià","zhī","xíng"],meaning:"矫正天下人的外在形态和行为。匡：矫正、规范。"},{term:"县跂仁义",pinyin:["xuán","qì","rén","yì"],meaning:"高悬仁义，使人踮脚企望。县通“悬”；跂：踮脚。"},{term:"慰天下之心",pinyin:["wèi","tiān","xià","zhī","xīn"],meaning:"安慰、安抚天下人的心。此处反说圣人以仁义控制人心。"},{term:"始踶跂好知",pinyin:["shǐ","zhì","qí","hào","zhī"],meaning:"开始踮脚用力，喜好机巧智术。踶跂：努力企及；好知：喜好智巧。"},{term:"争归于利",pinyin:["zhēng","guī","yú","lì"],meaning:"争相奔向利益。归：归向、趋向；利：利益。"},{term:"不可止也",pinyin:["bù","kě","zhǐ","yě"],meaning:"无法遏止。外在规范一旦激发争利与机巧，便形成自我加速的局面。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[t("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(g,{title:"残朴为器，工匠之罪；毁道德为仁义，圣人之过",subtitle:"善意，不能成为「治」的免责理由。",lines:[{text:"夫残朴以为器，工匠之罪也；毁道德以为仁义，圣人之过也。",tone:"定性",guide:"第三段开篇，两句极简洁的对仗——是第一段与第二段的直接收束，也是全篇的定性宣判：第一段说陶匠善治埴、匠人善治木——第三段说：残朴以为器，工匠之罪也；第二段说圣人蹩躠为仁、踶跂为义——第三段说：毁道德以为仁义，圣人之过也。「罪」与「过」——罪，是明确的罪行；过，是过失、错误——庄子用「过」而非「罪」来定性圣人，并非是在减轻圣人的责任——而是在说：圣人毁道德以为仁义，不是出于恶意（所以不用「罪」），而是出于善意的错误（所以用「过」）——但善意的错误，造成的伤害，不比恶意的罪行轻。"},{text:"夫马陆居则食草饮水，喜则交颈相靡，怒则分背相踢。马知已此矣！夫加之以衡扼，齐之以月题，而马知介倪闉扼鸷曼诡衔窃辔。故马之知而能至盗者，伯乐之罪也。",tone:"异化",guide:"定性之后，庄子再次回到马——但这一次，描绘的不是马的「真性」，而是马的「真知」，以及真知被异化之后的结果。马陆居则食草饮水，喜则交颈相靡，怒则分背相踢——四句话，是马在自然状态下的完整情感与本能——马知已此矣——马的「知」（本能与情感），到此为止——仅此而已。这一句，与第二段「民能已此矣」遥相呼应——「已此」——仅此——不是在说马很笨，不是在贬低马——而是在说：马的知，是完整的、自足的——喜怒饮食，已经是马全部的知——不需要更多，也不应该更多。然而——加之以衡扼，齐之以月题——给马套上车衡与颈轭，用月形装饰约束马头——这是伯乐「善治」之后的马的处境——而马知介倪闉扼鸷曼诡衔窃辔——马，学会了五种新的「知」：介倪（斜眼侧视，表示不驯）、闉扼（弯曲身体，抵抗颈轭）、鸷曼（凶猛抵触，拖延拖拽）、诡衔（诡诈地对付嚼子）、窃辔（暗中咬断缰绳）。这五种行为，是马在被「善治」之后发展出来的「新知」——但这个「新知」，是反抗、是欺骗、是盗窃——马，从「食草饮水·交颈相靡·分背相踢」，变成了「介倪·闉扼·鸷曼·诡衔·窃辔」——从自然的本能，变成了对抗束缚的技巧——从素朴的情感，变成了诡诈的手段。故马之知而能至盗者，伯乐之罪也——马的知，发展到能做出盗窃般行为的程度——这，是伯乐的罪。「善治」的代价，不只是死亡——还有异化：被「善治」的，即使活下来，也不再是原来的自己——而是一个被扭曲、被异化的自己。"},{text:"夫赫胥氏之时，民居不知所为，行不知所之，含哺而熙，鼓腹而游。民能已此矣！",tone:"含哺",guide:"马的异化，是对人的异化的预演——庄子将笔锋转向人，召唤出赫胥氏——传说中上古最本然时代的象征——民居不知所为，行不知所之（百姓居处，不知道该做什么；行走，不知道该去哪里——不是因为愚昧，而是因为无为——不是因为迷失，而是因为随性——本性自足，不需要「做」什么，不需要「去」哪里），含哺而熙，鼓腹而游（口含食物，嬉戏玩乐；拍着肚子，悠游自在——吃，是自然的；乐，是自然的——满足，不需要理由，不需要目的）。民能已此矣——百姓的「能」（本能），到此为止——仅此而已。与「马知已此矣」完全对应：马的知，仅此而已；民的能，仅此而已——「已此」，不是贫乏，不是不足，而是恰好：本性所需，恰好如此。「含哺而熙，鼓腹而游」——这八个字，是《马蹄》对「至德之世」最生动的描绘——比第二段的「填填颠颠」更具体，更温暖，更有画面感：一个孩子，嘴里含着食物，笑着跑来跑去；一个老人，拍着肚子，在田间悠游——没有仁义，没有礼乐，没有君子小人——只有含哺而熙，鼓腹而游。"},{text:"及至圣人，屈折礼乐以匡天下之形，县跂仁义以慰天下之心，而民乃始踶跂好知，争归于利，不可止也。此亦圣人之过也。",tone:"圣人之过",guide:"然后，是第三次「及至」——及至圣人，屈折礼乐以匡天下之形（强行用礼乐扭曲天下人的外在形态——坐要有坐相，站要有站相——把人的外在，纳入礼乐的框架），县跂仁义以慰天下之心（高悬仁义，让天下人踮脚企及，以此来「安慰」天下人的心——「县跂」——高悬，让人踮脚——这个意象极为精准：仁义，被高悬在那里——高到让人需要踮脚才能够到——圣人说：这是为了安慰你们的心。但庄子说：这不是安慰，这是折磨——让人永远踮着脚，永远够不到——不是安慰，是制造永恒的焦虑）。而民乃始踶跂好知，争归于利，不可止也——踶跂好知（踮脚努力，喜好机巧之知），争归于利（争相追逐利益），不可止也（无法停止）。这与马的「介倪闉扼鸷曼诡衔窃辔」完全对应——马被套上衡扼，学会了诡衔窃辔——民被套上礼乐仁义，学会了踶跂好知、争归于利——两者，是同一个逻辑，同一个悲剧。「不可止也」——这三个字，是《马蹄》最深的悲哀：一旦圣人用礼乐匡形、用仁义县跂——民的踶跂好知、争归于利，就再也停不下来了——因为本性已经被改变，素朴已经失去，赫胥氏之时，一去不返。此亦圣人之过也——《马蹄》全篇，以这一句作结。「亦」——也——这个字，与第一段结尾「此亦治天下者之过也」前后呼应：两个「亦」，暗示了一个未说出口的前提：圣人，还有更多的过——这里说的，只是其中之一。「圣人之过」——这四个字，是《马蹄》对儒家最直接的批判——儒家最推崇的，是圣人——尧、舜、禹、汤、文、武、周公——这些圣人，是儒家道德体系的基石。庄子说：圣人，是天下失去素朴的根源——圣人，有过。"}]}),i[15]||(i[15]=z(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·起（马之真性与善治之过）</span></span>
<span class="line"><span>    蹄践霜雪·齕草饮水·及至伯乐烧剔刻雒·死者过半</span></span>
<span class="line"><span>    → 善治之过：改造本性，即是伤害</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·立（至德之世）</span></span>
<span class="line"><span>    民有常性·织而衣耕而食·天放素朴·禽兽可系羁</span></span>
<span class="line"><span>    → 正面图景：至德之世，本性自足</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·合（圣人之过）</span></span>
<span class="line"><span>    残朴为器工匠之罪·毁道德为仁义圣人之过·含哺而熙鼓腹而游</span></span>
<span class="line"><span>    → 定性收束：善治的罪与过——民能已此矣</span></span></code></pre></div><p><strong>全篇主线</strong>：从马之真性被伯乐「善治」致死起，立至德之世的天放素朴，最终以「残朴为器，工匠之罪；毁道德为仁义，圣人之过」收束——你，已经够了，不需要被善治。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-《马蹄》的核心命题是什么" tabindex="-1">第一问：《马蹄》的核心命题是什么？ <a class="header-anchor" href="#第一问-《马蹄》的核心命题是什么" aria-label="Permalink to &quot;第一问：《马蹄》的核心命题是什么？&quot;">​</a></h3><blockquote><p><strong>「残朴以为器，工匠之罪也；毁道德以为仁义，圣人之过也。」</strong></p></blockquote><p>《马蹄》的核心命题，是**「善治」的罪与过**——用一句话概括：一切以「善」为名对本性进行改造的行为，都是罪与过——无论改造者是伯乐、工匠，还是圣人。</p><p>全篇的逻辑，建立在一个根本预设上：本性是完整自足的——马蹄践霜雪，马毛御风寒——民含哺而熙，鼓腹而游——这些，不需要任何人来「改善」。「善治」的问题，不在于动机——伯乐是善意的，圣人是善意的——问题在于「治」这个行为本身：治，就是用外在标准改造本性——改造，就是破坏——破坏，就是罪与过。</p><p>《马蹄》比《骈拇》更进一步的地方，在于：《骈拇》说仁义是多余的（侈于德）；《马蹄》说推行仁义的人，有罪与过——不只是结果有问题，行为本身就是问题。从「多余」到「致死」，从「侈于德」到「圣人之过」——批判的力度，更进一层。</p><h3 id="第二问-庄子说「圣人之过」-是否否定了一切文明" tabindex="-1">第二问：庄子说「圣人之过」，是否否定了一切文明？ <a class="header-anchor" href="#第二问-庄子说「圣人之过」-是否否定了一切文明" aria-label="Permalink to &quot;第二问：庄子说「圣人之过」，是否否定了一切文明？&quot;">​</a></h3><p>这是读《马蹄》最容易产生的疑问——庄子说圣人有过，说礼乐仁义破坏了素朴——是否意味着庄子在呼吁回到蒙昧，拒绝一切文明成就？</p><p>答案是：<strong>不是。</strong></p><p>庄子的批判，有一个精准的指向——不是文明本身，而是「以善治为名的强制改造」：第一段说埴木之性，岂欲中规矩钩绳——批判的，是强加——不是说圆的器物不好，而是说强迫埴木变成圆的，是罪；第二段说道德不废，安取仁义——批判的，是以仁义替代道德——不是说仁义本身是坏的，而是说用仁义填补道德被废弃后的空缺，是错的；第三段说圣人屈折礼乐、县跂仁义——批判的，是强制与高压——不是说礼乐仁义没有价值，而是说用强制扭曲和高悬标准的方式推行，是过。</p><p><strong>庄子的立场，不是「回到蒙昧」，而是「不强制改造本性」</strong>——如果礼乐仁义，是从本性自然流出的——就像马自然地食草饮水，就像民自然地织而衣、耕而食——那它不是「善治」，而是「天放」。「天放」，才是庄子真正肯定的——不是蒙昧，不是无序，而是本性的自然流淌，不受强制。</p><h3 id="第三问-《马蹄》在《庄子》外篇中处于什么位置" tabindex="-1">第三问：《马蹄》在《庄子》外篇中处于什么位置？ <a class="header-anchor" href="#第三问-《马蹄》在《庄子》外篇中处于什么位置" aria-label="Permalink to &quot;第三问：《马蹄》在《庄子》外篇中处于什么位置？&quot;">​</a></h3><p>《马蹄》是外篇第二篇，与《骈拇》（外篇第一）、《应帝王》（内篇终篇）构成庄子批判主题的核心链条：</p><table tabindex="0"><thead><tr><th>篇目</th><th>位置</th><th>核心批判</th><th>关键词</th></tr></thead><tbody><tr><td>《应帝王》</td><td>内篇终篇</td><td>以己出经式义度·欺德·浑沌凿窍</td><td>欺德·无为·顺物自然</td></tr><tr><td>《骈拇》</td><td>外篇第一</td><td>仁义聪明是骈枝·以物易性·适人之适</td><td>骈枝·常然·自适其适</td></tr><tr><td>《马蹄》</td><td>外篇第二</td><td>善治是罪与过·伯乐·圣人</td><td>真性·天放·素朴·圣人之过</td></tr></tbody></table><p>三篇的递进关系：《应帝王》建立命题——干涉本身是伤害；《骈拇》解构内容——仁义这个内容是骈枝；《马蹄》追问责任——推行仁义的圣人，有过。从命题，到内容，到责任——庄子的批判，越来越具体，越来越直接。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>「善治」与管理</strong></p><blockquote><p>现代社会，充满了各种形式的「伯乐」：管理者说「我善治团队」——KPI、绩效考核、标准化流程——每一项「善治」，都是一套衡扼月题；教育者说「我善治学生」——统一课程、标准考试、排名评级——每一项「善治」，都是一套烧剔刻雒。庄子的问题是：你的「善治」，有没有问过被治者的本性？是从本性出发，还是从标准出发？从本性出发，是天放；从标准出发，是伯乐——两者的区别，不在于结果好不好，而在于出发点是谁的。</p></blockquote><p><strong>「含哺而熙」与现代焦虑</strong></p><blockquote><p>「含哺而熙，鼓腹而游」——这八个字，是《马蹄》送给现代人最深的礼物——你上一次「含哺而熙」，是什么时候？你上一次「鼓腹而游」，是什么时候？不是说吃饱了就满足——而是说：那种吃饱了、没有目的、没有焦虑、就这样悠游自在的状态——你还记得吗？「民能已此矣」——民的本能，到此为止，仅此而已——这不是贫乏，这是完整。现代人的困境，恰恰是：吃饱了，还要焦虑下一顿；有房了，还要焦虑下一套；成功了，还要焦虑下一个目标——「争归于利，不可止也」——这不是人的本性，这是被「善治」之后的异化。庄子的问题是：你的焦虑，有多少是本性的需要，有多少是别人「县跂」给你的标准？</p></blockquote><p><strong>「马知至盗」与制度异化</strong></p><blockquote><p>这是《马蹄》最深的一个洞见：善治，不只让被治者死亡——还让活下来的被治者，发展出对抗善治的技巧——介倪·闉扼·鸷曼·诡衔·窃辔。这在现代社会，随处可见：制度越严格，钻空子的技巧越精妙；考核越细密，应付考核的手段越高明；规范越繁琐，绕过规范的方法越多样。这不是人的本性坏——这是「善治」逼出来的——是伯乐之罪，不是马之罪。当一个制度制造出大量「诡衔窃辔」的行为时，问题不在于被治者，而在于治理本身——是治理，逼出了这些行为。</p></blockquote><p><strong>「道德不废，安取仁义」与规则的本质</strong></p><blockquote><p>这两句，是对规则本质最深的追问：规则（仁义礼乐）是什么时候出现的？是本性完整的时候，还是本性失去之后？庄子的答案：是本性失去之后——道德不废，不需要仁义；性情不离，不需要礼乐——仁义礼乐的出现，本身就证明了道德已废、性情已离。这对现代社会的启示：当一个社会需要越来越多的规则来维持秩序时，这不是进步的标志——而是本性失去的标志。规则越多，意味着本性失去越多；法律越繁密，意味着道德越稀薄——真正的问题，不是如何制定更好的规则，而是：如何让本性不再失去。</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>马之真性</td><td>第1段</td><td>践霜雪·御风寒·齕草饮水·翘足而陆·完整自足</td></tr><tr><td>义台路寝</td><td>第1段</td><td>华美宫室·人的标准·对马的本性无用</td></tr><tr><td>及至伯乐</td><td>第1段</td><td>善治的起点·本然状态的第一次终结</td></tr><tr><td>烧剔刻雒</td><td>第1段</td><td>四项改造·逐项破坏马的真性</td></tr><tr><td>羁絷皂栈</td><td>第1段</td><td>络头绊索·马槽马棚·束缚与圈养</td></tr><tr><td>死者十二三·死者过半</td><td>第1段</td><td>善治的代价·两阶段死亡</td></tr><tr><td>埴木之性·岂欲中规矩钩绳</td><td>第1段</td><td>本性不欲被外在标准规范</td></tr><tr><td>此亦治天下者之过</td><td>第1段</td><td>称赞善治·本身也是过失</td></tr><tr><td>常性</td><td>第2段</td><td>民恒常的本性·织而衣·耕而食</td></tr><tr><td>同德</td><td>第2段</td><td>共同保有本真之德的状态</td></tr><tr><td>天放</td><td>第2段</td><td>天然放任·本性自然流淌·不受强制</td></tr><tr><td>至德之世</td><td>第2段</td><td>德性最完整的时代·本然状态的描述</td></tr><tr><td>填填颠颠</td><td>第2段</td><td>行走安稳·目光专注·内在安定</td></tr><tr><td>山无蹊隧·泽无舟梁</td><td>第2段</td><td>人不征服自然·自然与人和谐共处</td></tr><tr><td>禽兽可系羁而游</td><td>第2段</td><td>人与自然的本然亲密·无恐惧无对立</td></tr><tr><td>恶乎知君子小人</td><td>第2段</td><td>至德之世无君子小人之分</td></tr><tr><td>素朴</td><td>第2段</td><td>未染色的丝·未加工的木·本然状态</td></tr><tr><td>素朴而民性得矣</td><td>第2段</td><td>素朴是民性得以保全的状态</td></tr><tr><td>蹩躠为仁·踶跂为义</td><td>第2段</td><td>费力推行仁义·仁义非本性的证明</td></tr><tr><td>天下始疑·天下始分</td><td>第2段</td><td>圣人出·内在动摇·外在分裂</td></tr><tr><td>纯朴不残·孰为牺尊</td><td>第2段</td><td>有牺尊必先残纯朴·文明以本然为代价</td></tr><tr><td>道德不废·安取仁义</td><td>第2段</td><td>仁义是道德被废后的替代品</td></tr><tr><td>性情不离·安用礼乐</td><td>第2段</td><td>礼乐是性情离散后的约束工具</td></tr><tr><td>残朴以为器·工匠之罪</td><td>第3段</td><td>破坏原木制器·工匠的罪</td></tr><tr><td>毁道德以为仁义·圣人之过</td><td>第3段</td><td>破坏道德推行仁义·圣人的过</td></tr><tr><td>马知已此矣</td><td>第3段</td><td>马的本然之知·仅此而已·完整自足</td></tr><tr><td>衡扼月题</td><td>第3段</td><td>车衡颈轭·马头装饰·善治的工具</td></tr><tr><td>介倪闉扼鸷曼诡衔窃辔</td><td>第3段</td><td>马被善治后发展出的异化之知</td></tr><tr><td>马之知至盗·伯乐之罪</td><td>第3段</td><td>善治致异化·异化的责任在治者</td></tr><tr><td>赫胥氏之时</td><td>第3段</td><td>上古最本然时代的象征</td></tr><tr><td>含哺而熙·鼓腹而游</td><td>第3段</td><td>本然满足·无目的·无焦虑</td></tr><tr><td>民能已此矣</td><td>第3段</td><td>民的本然之能·仅此而已·完整自足</td></tr><tr><td>屈折礼乐·匡天下之形</td><td>第3段</td><td>强制用礼乐规范外在形态</td></tr><tr><td>县跂仁义·慰天下之心</td><td>第3段</td><td>高悬仁义·制造永恒焦虑</td></tr><tr><td>踶跂好知·争归于利·不可止</td><td>第3段</td><td>善治后的异化·无法停止</td></tr><tr><td>此亦圣人之过也</td><td>第3段</td><td>全篇结语·与第一段「亦」字呼应</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><blockquote><p><strong>「含哺而熙，鼓腹而游。民能已此矣！」</strong></p></blockquote><p>民能已此——本性所需，仅此而已——不多，不少，不需要任何人来「善治」。一切「善治」——无论是伯乐的烧剔刻雒，还是圣人的屈折礼乐、县跂仁义——都是在说：你现在的样子，不够好——你需要被改造。庄子说：不。马蹄，可以践霜雪——已经够了；民，含哺而熙，鼓腹而游——已经够了。<strong>你，已经够了。你的本性，不需要被「善治」。含哺而熙，鼓腹而游——这，就是天放。</strong></p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·马蹄》</li></ul>`,35))])}}});export{f as __pageData,j as default};
